from django.db import migrations, models
from django.utils import timezone


def populate_yearly_campaigns(apps, schema_editor):
    Campaign = apps.get_model("valentine", "ValentineCampaign")
    PlatformSettings = apps.get_model("valentine", "Settings")
    Valentine = apps.get_model("valentine", "Valenitines")

    platform_settings = PlatformSettings.objects.order_by("pk").first()
    latest_message = Valentine.objects.order_by("-date").first()
    if platform_settings:
        if platform_settings.reveal_at:
            active_year = platform_settings.reveal_at.year
        else:
            active_year = platform_settings.reveal_date.year
    elif latest_message:
        active_year = latest_message.date.year
    else:
        return

    message_years = set(
        Valentine.objects.values_list("date__year", flat=True).distinct()
    )
    campaign_years = message_years | {active_year}
    archived_at = timezone.now()
    campaigns = {}

    for year in campaign_years:
        is_archived = year != active_year
        campaign = Campaign.objects.create(
            year=year,
            name=f"Valentine {year}",
            is_archived=is_archived,
            archived_at=archived_at if is_archived else None,
        )
        campaigns[year] = campaign

    for year in message_years:
        Valentine.objects.filter(date__year=year).update(
            campaign_id=campaigns[year].pk
        )

    if platform_settings:
        PlatformSettings.objects.filter(pk=platform_settings.pk).update(
            active_campaign_id=campaigns[active_year].pk
        )


